export const motherRoomDefaults={historyMotherEnabled:true,historyMotherGrayscale:0,historyMotherSurfaces:[],historyMotherSpeed:1,historyMotherFocal:850,historyMotherPush:220,historyMotherFocusX:.57,historyMotherFocusY:.4,historyMotherStart:0,historyMotherFinish:1,historyMotherPersonDepth:1500,historyMotherVaseDepth:900,historyMotherClothDepth:2000,historyMotherWallDepth:2200,historyMotherPersonX:390,historyMotherPersonY:88,historyMotherPersonWidth:380,historyMotherVaseX:-160,historyMotherVaseY:310,historyMotherVaseWidth:510,historyMotherClothX:90,historyMotherClothY:125,historyMotherClothWidth:205,historyMotherVaseBlur:2.5,historyMotherBackgroundBlur:.3,historyMotherPersonBrightness:1,historyMotherLight:1,historyMotherShadow:.23};
export function motherRoomSettings(input={}){const f={...motherRoomDefaults,...input},out={...portraitRoomDefaults};for(const [key,value]of Object.entries(f))if(key.startsWith('historyMother'))out[key.replace('historyMother','historyRoom')]=value;out.historySourceBindings={};for(const suffix of ['Background','Person','Vase','Cloth'])out.historySourceBindings['historyRoom'+suffix]=f.historySourceBindings?.['historyMother'+suffix]||'historyMother'+suffix;return out;}
